import 'package:hive/hive.dart';

part 'category.g.dart';

/// A transaction category.
///
/// Categories are shared between income and expenses and are chosen by
/// the user when creating a transaction or a template.
///
/// Extends [HiveObject] for local persistence.
/// The [TypeAdapter] is generated by `hive_generator` in `category.g.dart`.
///
/// Fields:
/// - [id]: unique identifier (timestamp in milliseconds)
/// - [name]: category name (e.g. "Groceries", "Transport")
@HiveType(typeId: 2)
class Category extends HiveObject {
  @HiveField(0)
  final String id;

  @HiveField(1)
  final String name;

  Category({
    required this.id,
    required this.name,
  });
}
